from svg import box, t, svg

TILES = [('1', 'THE END IS NEAR', 'a deadline in the doctrine'), ('2', 'THEY ARE COMING', 'a persecution story'),
         ('3', 'A SHAKY LEADER', 'ill, exposed, losing grip'), ('4', 'SEALED OFF', 'no outside checks'),
         ('5', 'THE MEANS', 'weapons, chemicals, a compound'), ('6', 'NO WAY BACK', 'retreat feels like death')]
FIG = svg(1180, 400, 'Six risk factors for violence in high-demand groups',
          ''.join(box(20 + (i % 3) * 390, 20 + (i // 3) * 160, 360, 140, 's-box-a' if i in (2, 5) else 's-card') +
                  t(70 + (i % 3) * 390, 98 + (i // 3) * 160, n, 's-t-d') +
                  t(230 + (i % 3) * 390, 80 + (i // 3) * 160, a, 's-t') + t(230 + (i % 3) * 390, 114 + (i // 3) * 160, b, 's-t-sm')
                  for i, (n, a, b) in enumerate(TILES)) +
          t(590, 362, 'One tile is common and usually harmless. Several at once, under pressure, is the danger.', 's-t-b') +
          t(590, 390, 'Orange: the two that outsiders can most influence, by how they treat the leader and whether they leave a door open', 's-t-sm'))

